// yamlResolver.mjs — YAML 1.1 scalar tag resolution and scalar construction,
// replicating PyYAML's SafeLoader/SafeConstructor behavior.
//
// All matching is done with hand-written character scanners; no regular
// expressions and no JSON helpers are used anywhere in this module.
//
// Value shapes returned (the inter-module contract):
//   null      -> null
//   bool      -> true / false
//   int       -> number (safe range) or BigInt
//   float     -> number (Infinity / -Infinity / NaN included)
//   str       -> string
//   timestamp -> { __yamlTag: 'tag:yaml.org,2002:timestamp', __yamlText: <canonical> }
//   binary    -> { __yamlTag: 'tag:yaml.org,2002:binary',    __yamlText: <base64> }

export const YAML_TAG_PREFIX = 'tag:yaml.org,2002:';

// A scalar equal to `<<` resolves to the merge tag; the parser treats this
// specially in key position and rejects it in value position.
export const MERGE_TAG = 'tag:yaml.org,2002:merge';

const BOOL_WORDS = {
  yes: true, Yes: true, YES: true,
  no: false, No: false, NO: false,
  true: true, True: true, TRUE: true,
  false: false, False: false, FALSE: false,
  on: true, On: true, ON: true,
  off: false, Off: false, OFF: false,
};

function isDigit(c) {
  return c >= '0' && c <= '9';
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

// ---------------------------------------------------------------------------
// Implicit resolvers (pattern matchers mirroring PyYAML's resolver regexes)
// ---------------------------------------------------------------------------

// ^(?:~|null|Null|NULL|)$
export function matchNull(s) {
  return s === '' || s === '~' || s === 'null' || s === 'Null' || s === 'NULL';
}

// ^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$
export function matchBool(s) {
  return Object.prototype.hasOwnProperty.call(BOOL_WORDS, s);
}

// ^(?:[-+]?0b[0-1_]+|[-+]?0[0-7_]+|[-+]?(?:0|[1-9][0-9_]*)|[-+]?0x[0-9a-fA-F_]+|[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$
export function matchInt(s) {
  let i = 0;
  if (s[i] === '-' || s[i] === '+') i++;
  const rest = s.slice(i);
  if (rest.length === 0) return false;

  // binary: 0b[0-1_]+
  if (rest[0] === '0' && rest[1] === 'b') {
    if (rest.length === 2) return false;
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j];
      if (c !== '0' && c !== '1' && c !== '_') return false;
    }
    return true;
  }
  // hex: 0x[0-9a-fA-F_]+
  if (rest[0] === '0' && rest[1] === 'x') {
    if (rest.length === 2) return false;
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j];
      if (!isHexDigit(c) && c !== '_') return false;
    }
    return true;
  }
  // sexagesimal: [1-9][0-9_]*(?::[0-5]?[0-9])+
  if (rest[0] >= '1' && rest[0] <= '9') {
    let j = 0;
    while (j < rest.length && (isDigit(rest[j]) || rest[j] === '_')) j++;
    if (j < rest.length && rest[j] === ':') {
      // one or more :dd groups (1-2 digits, first 0-5)
      let k = j;
      let groups = 0;
      while (k < rest.length && rest[k] === ':') {
        k++;
        let d = 0;
        while (k < rest.length && isDigit(rest[k]) && d < 2) { k++; d++; }
        if (d === 0) return false;
        // group value must match [0-5]?[0-9]: single digit, or two digits with first 0-5
        const grp = rest.slice(k - d, k);
        if (d === 2 && !(grp[0] >= '0' && grp[0] <= '5')) return false;
        groups++;
      }
      return k === rest.length && groups > 0;
    }
    // decimal: [1-9][0-9_]*
    return j === rest.length;
  }
  // octal: 0[0-7_]+  (also plain "0" is decimal)
  if (rest[0] === '0') {
    if (rest.length === 1) return true; // "0"
    for (let j = 1; j < rest.length; j++) {
      const c = rest[j];
      if (!((c >= '0' && c <= '7') || c === '_')) return false;
    }
    return true;
  }
  return false;
}

// ^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?|\.[0-9_]+(?:[eE][-+][0-9]+)?
//   |[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*|[-+]?\.(?:inf|Inf|INF)|\.(?:nan|NaN|NAN))$
export function matchFloat(s) {
  // .inf / .nan forms
  let body = s;
  let i = 0;
  if (body[i] === '-' || body[i] === '+') i++;
  const afterSign = body.slice(i);
  if (afterSign === '.inf' || afterSign === '.Inf' || afterSign === '.INF') return true;
  if (s[0] !== '-' && s[0] !== '+') {
    if (s === '.nan' || s === '.NaN' || s === '.NAN') return true;
  }

  // sexagesimal float: [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
  {
    let j = i;
    if (j < s.length && isDigit(s[j])) {
      let k = j;
      while (k < s.length && (isDigit(s[k]) || s[k] === '_')) k++;
      // try sexagesimal: requires at least one :group then a dot
      let m = k;
      let groups = 0;
      let ok = true;
      while (m < s.length && s[m] === ':') {
        m++;
        let d = 0;
        while (m < s.length && isDigit(s[m]) && d < 2) { m++; d++; }
        if (d === 0) { ok = false; break; }
        const grp = s.slice(m - d, m);
        if (d === 2 && !(grp[0] >= '0' && grp[0] <= '5')) { ok = false; break; }
        groups++;
      }
      if (ok && groups > 0 && m < s.length && s[m] === '.') {
        m++;
        while (m < s.length && (isDigit(s[m]) || s[m] === '_')) m++;
        if (m === s.length) return true;
      }
    }
  }

  // decimal float: [-+]?([0-9][0-9_]*\.[0-9_]*|\.[0-9_]+)([eE][-+][0-9]+)?
  {
    let j = i;
    let saw = false;
    if (j < s.length && isDigit(s[j])) {
      while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
      if (j < s.length && s[j] === '.') {
        j++;
        while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
        saw = true;
      }
    } else if (j < s.length && s[j] === '.') {
      j++;
      const start = j;
      while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
      if (j > start) saw = true; // \.[0-9_]+ requires at least one char
    }
    if (!saw) return false;
    // optional exponent — sign is REQUIRED (matches the executable: 1.5e3 is a str)
    if (j < s.length && (s[j] === 'e' || s[j] === 'E')) {
      j++;
      if (j < s.length && (s[j] === '-' || s[j] === '+')) j++;
      else return false;
      const start = j;
      while (j < s.length && isDigit(s[j])) j++;
      if (j === start) return false;
    }
    return j === s.length;
  }
}

// Timestamp matcher; on success returns the captured components, else null.
// ^(?:[0-9]{4}-[0-9]{2}-[0-9]{2}
//   |[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}(?:[Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}
//     (?:\.[0-9]*)?(?:[ \t]*(?:Z|[-+][0-9]{1,2}(?::[0-9]{2})?))?)$
export function matchTimestamp(s) {
  const n = s.length;
  // date-only form needs exactly 10 chars
  if (n === 10 &&
      isDigit(s[0]) && isDigit(s[1]) && isDigit(s[2]) && isDigit(s[3]) &&
      s[4] === '-' && isDigit(s[5]) && isDigit(s[6]) &&
      s[7] === '-' && isDigit(s[8]) && isDigit(s[9])) {
    return {
      year: +s.slice(0, 4), month: +s.slice(5, 7), day: +s.slice(8, 10),
      dateOnly: true,
    };
  }
  // datetime form
  let i = 0;
  if (n < 15) return null;
  for (let k = 0; k < 4; k++) { if (!isDigit(s[i + k])) return null; }
  const year = +s.slice(0, 4);
  i = 4;
  if (s[i] !== '-') return null;
  i++;
  let start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const month = +s.slice(start, i);
  if (s[i] !== '-') return null;
  i++;
  start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const day = +s.slice(start, i);
  // separator: T, t, or one/more spaces/tabs
  if (s[i] === 'T' || s[i] === 't') {
    i++;
  } else if (s[i] === ' ' || s[i] === '\t') {
    while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  } else {
    return null;
  }
  // hour: 1-2 digits
  start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const hour = +s.slice(start, i);
  if (s[i] !== ':') return null;
  i++;
  // minute: exactly 2 digits
  if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
  const minute = +(s[i] + s[i + 1]);
  i += 2;
  if (s[i] !== ':') return null;
  i++;
  // second: exactly 2 digits
  if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
  const second = +(s[i] + s[i + 1]);
  i += 2;
  // optional fraction: .[0-9]*
  let fraction = '';
  if (s[i] === '.') {
    i++;
    start = i;
    while (i < n && isDigit(s[i])) i++;
    fraction = s.slice(start, i);
  }
  // optional timezone: [ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?)
  let tz = null;
  while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  if (i < n) {
    if (s[i] === 'Z') {
      tz = { sign: '+', hour: 0, minute: 0 };
      i++;
    } else if (s[i] === '-' || s[i] === '+') {
      const sign = s[i];
      i++;
      start = i;
      while (i < n && isDigit(s[i]) && i - start < 2) i++;
      if (i === start) return null;
      const tzh = +s.slice(start, i);
      let tzm = 0;
      if (s[i] === ':') {
        i++;
        if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
        tzm = +(s[i] + s[i + 1]);
        i += 2;
      }
      tz = { sign, hour: tzh, minute: tzm };
    } else {
      return null;
    }
  }
  if (i !== n) return null;
  return { year, month, day, hour, minute, second, fraction, tz, dateOnly: false };
}

// ---------------------------------------------------------------------------
// Constructors (mirror PyYAML SafeConstructor)
// ---------------------------------------------------------------------------

function stripUnderscores(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) if (s[i] !== '_') out += s[i];
  return out;
}

function toSafeNumberOrBigInt(big) {
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  const min = BigInt(Number.MIN_SAFE_INTEGER);
  if (big <= max && big >= min) return Number(big);
  return big;
}

export function constructInt(raw) {
  let value = stripUnderscores(raw);
  let sign = 1n;
